import re

def fn_address_check(addresses):
  nz_po_address_pattern = re.compile(
    r'\b(?:P(?:\.|ost)?\s*O(?:\.|ffice)?\.?\s*Box\s*\d+|'      # e.g., P.O. Box 123, Post Office Box 123
    r'Private\s+Bag\s*\d+|'                                     # e.g., Private Bag 1234
    r'Poste\s+Restante)\b'                                      # e.g., Poste Restante
    r'(?:,\s*[\w\s\-]+)*'                                       # optional: suburb or city, e.g., Auckland Central
    r'(?:,\s*(?:NZ|New Zealand))?'                              # optional: country
    , re.IGNORECASE
)
  for address in addresses:
      match = nz_po_address_pattern.search(address)
      if match:
          return "FAIL"
  return "PASS"


def fn_order_value_check(order_value):
  order_value = float(order_value)
  if order_value is None or order_value == "":
    return "FAIL"

  if order_value > 0 and order_value < 1200:
    return "PASS"
  else: return "FAIL"

# Loop over input items and add a new field called 'myNewField' to the JSON of each one
for item in _input.all():
  item.json.address_check = fn_address_check([item.json.address1, str(item.json.address2)])

  item.json.order_value_check = fn_order_value_check(item.json.current_subtotal_price)

  if item.json.address_check=="PASS" and item.json.order_value_check == "PASS":
    item.json.all_check = "PASS"
  else:
    item.json.all_check = "FAIL"

return _input.all()
